[CmdletBinding()]
param([string]$ProjectRoot)
$ErrorActionPreference='Stop';if([string]::IsNullOrWhiteSpace($ProjectRoot)){$ProjectRoot=(Get-Location).Path}
$validator=Join-Path $ProjectRoot 'ES/Automation/ABCD/Test-ESABCEngineeringCompetitionResult.ps1';$contract=Join-Path $ProjectRoot 'ES/Automation/Contracts/es-ai-abc-engineering-architecture-competition-v1.schema.json';$hash=(Get-FileHash -LiteralPath $contract -Algorithm SHA256).Hash.ToLowerInvariant();$base=[ordered]@{schemaVersion=1;contractId='es://automation/contracts/ai-abc/engineering-architecture-competition/v1';contractHash=$hash;status='completed';completionEligible=$true;evidenceSummary=[ordered]@{eligibleCount=2;implementationEvidenceVerifiedCount=2;independentReplayVerifiedCount=2;providerScoreComparisonStatus='stable';counterfactualPositiveCount=2;generationImprovedCount=2;generationNoIncrementCount=0;contractHashBound=$true};generationCount=3;generationHistory=@(@{generation=1},@{generation=2},@{generation=3});paretoShortlist=@('a','b');winnerId='a';runtimeStatus='runtime-not-run'};$p=[IO.Path]::GetTempFileName();try{$base|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $p -Encoding UTF8;powershell -NoProfile -ExecutionPolicy Bypass -File $validator -ResultPath $p -ProjectRoot $ProjectRoot|Out-Null;$valid=$LASTEXITCODE;$base.completionEligible=$false;$base|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $p -Encoding UTF8;powershell -NoProfile -ExecutionPolicy Bypass -File $validator -ResultPath $p -ProjectRoot $ProjectRoot|Out-Null;$tampered=$LASTEXITCODE;$pass=($valid -eq 0 -and $tampered -ne 0);$state='failed';if($pass){$state='passed'};[pscustomobject]@{status=$state;validExit=$valid;tamperedExit=$tampered};if(-not $pass){exit 1}}finally{Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue}
